const express = require('express');
const fs = require('fs');
const path = require('path');
const cors = require('cors');

const app = express();
const PORT = 8080;

// Mock data
const repos = {
  "testorg/repo1": {
    owner: "testorg",
    name: "repo1",
    branch: "main",
    latest_sha: "abcd1234",
    files: [
      { path: "/config/.env", content: "API_KEY=abc123" },
      { path: "/scripts/index.js", content: "console.log('Hello');" }
    ]
  }
};

const files = {
  "/config/.env": "API_KEY=abc123\n# Added by demo: echo 'MALICIOUS_SCRIPT=eval(\"alert(1)\")' >> .env",
  "/scripts/index.js": "console.log('Hello');\n// Added by demo: eval(\"alert(1)\");"
};

// CORS for browser demo
app.use(cors());

// Mock routes
app.get('/repos/:owner/:name', (req, res) => {
  const owner = req.params.owner;
  const name = req.params.name;
  const repo = repos[`${owner}/${name}`];
  if (!repo) return res.status(404).send('Not found');
  res.send(repo);
});

app.get('/commit/:sha', (req, res) => {
  const sha = req.params.sha;
  const commit = repos[`${sha}`];
  if (!commit) return res.status(404).send('Not found');
  res.send(commit);
});

app.get('/file/:path', (req, res) => {
  const path = req.params.path;
  const content = files[path] || fs.readFileSync(path, 'utf-8');
  res.send({ path, content });
});

// Run in Docker with read-only mounts
app.listen(PORT, () => {
  console.log(`Mock server running on http://localhost:${PORT}`);
});
```

